  flex-wrap: wrap;
  gap: 28px;
  margin: 36px 0 0 0;
}

.pet-card {
  background: #232323;
  border-radius: 14px;
  padding: 22px 20px 16px 20px;
  min-width: 232px;
  max-width: 256px;
  box-shadow: 0 2px 10px 0 rgba(40,40,40,0.16);
  display: flex;
  flex-direction: column;
  align-items: center;
  position: relative;
  border: 1px solid var(--border-color);
  margin-bottom: 12px;
}

.pet-avatar-container {
  margin-bottom: 16px;
  display: flex; align-items: center; justify-content: center;
}
.pet-avatar-img {
  width: 70px; height: 70px; object-fit: cover; border-radius: 36px;
  border: 3px solid var(--kavia-orange);
  background: #191919;
}
.pet-avatar-fallback {
  width: 70px; height: 70px; border-radius: 36px;
  display: flex; align-items: center; justify-content: center;
  font-size: 2.0rem;
  font-weight: 500;
  color: #FEFEFE;
  background: var(--kavia-orange);
  border: 3px solid var(--kavia-orange);
  letter-spacing: 2px;
}

.pet-info {
  text-align: center;
  margin-bottom: 6px;
}

.pet-name {
  font-size: 1.35rem;
  font-weight: 600;
  color: var(--text-color);
}
.pet-meta {
  color: var(--text-secondary);
  font-size: 0.92rem;
  margin-top: 2px;
}
.pet-breed {
  margin-left: 5px;
}
.pet-age {
  display: block;
  margin-top: 4px;
}

.pet-actions {
  display: flex;
  gap: 12px;
  margin-top: 12px;
}

.btn-small {
  font-size: 0.98rem;
  padding: 6px 12px;
  border-radius: 6px;
}

.btn-danger, .btn.btn-danger {
  background: #e24141 !important;
  color: #fff !important;
  border: none;
}

.pet-empty-msg {
  text-align: center;
}

.pet-modal-overlay {
  position: fixed;
  left:0; top:0; width:100vw; height:100vh;
  z-index: 888;
  background: rgba(18,18,18,0.78);
  display: flex;
  align-items: center;
  justify-content: center;
}
.pet-modal {
  background: #1F1B22;
  border-radius: 12px;
  padding: 32px 28px 26px 28px;
  min-width: 320px;
  max-width: 99vw;
  min-height: 90px;
  color: var(--text-color);
  box-shadow: 0 10px 48px 0 rgba(0,0,0,0.39);
  z-index: 1000;
}
.pet-form-row {
  margin-bottom: 18px;
  display: flex;
  flex-direction: column;
}
