  font-weight: 500;
  color: var(--text-secondary);
  margin-bottom: 4px;
  font-size: 1.05rem;
}
.pet-form-row input[type="text"] {
  width: 100%;
  background: #181818;
  color: #faebd7;
  border: 1px solid var(--border-color);
